// Resolve a name → fully-qualified URL respecting the Vite base path
// ('/noticehub/' on GH Pages, '/' in dev). Returns null when the org
// isn't in the map (either unknown or known-missing).
export function iconFor(orgName) {
  const path = ORG_ICON_MAP[orgName]
  if (!path) return null
  return import.meta.env.BASE_URL + path
}
